<template><aside class="skill-tree"><ul><SkillTreeNode v-for="item in tree" :key="item.path||item.name" :item="item" :selected="modelValue" @select="$emit('update:modelValue',$event)" /></ul></aside></template>
<script setup>import{computed}from"vue";import SkillTreeNode from"./SkillTreeNode.vue";const props=defineProps({files:Array,modelValue:String});defineEmits(["update:modelValue"]);const tree=computed(()=>{const root=[];(props.files||[]).forEach(file=>{let nodes=root;file.path.split("/").filter(Boolean).forEach((name,index,parts)=>{const path=parts.slice(0,index+1).join("/");let node=nodes.find(item=>item.name===name);if(!node){node={name,path,type:index===parts.length-1?"file":"directory",children:[]};nodes.push(node);}nodes=node.children;});});const sort=items=>items.sort((a,b)=>a.type===b.type?a.name.localeCompare(b.name):a.type==="directory"?-1:1).map(item=>({...item,children:sort(item.children)}));return sort(root);});</script>
